import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const u=JSON.parse('{"title":"创游世界战斗系统设计入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界战斗系统设计入门.md","filePath":"脚本系统/专题研究/创游世界战斗系统设计入门.md","lastUpdated":1777893104000}'),d={name:"脚本系统/专题研究/创游世界战斗系统设计入门.md"};function h(o,l,c,n,t,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界战斗系统设计入门" tabindex="-1">创游世界战斗系统设计入门 <a class="header-anchor" href="#创游世界战斗系统设计入门" aria-label="Permalink to “创游世界战斗系统设计入门”">​</a></h1><blockquote><p>一句话摘要：这篇文档讲的是创游世界战斗系统的最小可扩展骨架，包括生命、伤害、武器、子弹、状态、命中流程与 UI 反馈应该怎样拆分，避免把所有逻辑糊成一团。</p><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p><p>关键词：战斗系统, 生命, 伤害, 武器槽, 子弹, 状态机, UI反馈, 命中流程</p><p>适用版本：以 <code>4.56.18b27</code> 脚本界面截图为主证据，并结合教程与视频案例交叉整理</p><p>当前状态：已深度整理</p><p>可信度：<code>[已确认]</code> + <code>部分[高可信推断]</code></p><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/广播与事件机制导航.md</code>、<code>docs/核心研究/数据、变量与作用域导航.md</code></p></blockquote><ul><li>分类：脚本</li><li>子系统：战斗 / 生命 / 伤害 / 武器 / 状态 / UI反馈</li><li>关键词标签：战斗系统, 生命, 伤害, 武器槽, 近战武器, 远程武器, 子弹, 血条, Buff, 闪避, 翻滚</li><li>来源类型：脚本界面截图 + 官方教程 + B站视频主题归纳</li><li>证据等级：截图直接证据 + 多来源交叉归纳</li><li>完整度状态：深度整理</li><li>版本号：4.56.18b27（脚本界面截图主证据）</li><li>来源文件：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code>, <code>docs/OCR资料/官方教程截图转文本索引.md</code>, <code>docs/教程资料/官方教程知识索引.md</code>, <code>docs/教程资料/B站创游世界视频资源清单.md</code></li><li>来源截图编号：215325, 215534, 112406, 112424, 112435, 112546</li><li>最后更新：2026-04-20</li><li>适合查询：战斗系统怎么起步、生命和伤害怎么组织、武器与UI怎么配合、动作战斗项目先做什么</li></ul><h2 id="_1-文档目标" tabindex="-1">1. 文档目标 <a class="header-anchor" href="#_1-文档目标" aria-label="Permalink to “1. 文档目标”">​</a></h2><p>这篇不是逐条罗列所有战斗积木，而是回答一个更实战的问题：</p><blockquote><p><strong>如果我要在创游世界里做一个能打、能掉血、能显示反馈、还能继续扩展的战斗系统，最小架构应该怎么搭？</strong></p></blockquote><p>适合对象：</p><ul><li>已经会基础摆物体、挂组件、写一点脚本</li><li>想从“会拼功能”进到“会搭系统”</li><li>打算做 RPG、横版动作、射击、闯关、Boss 战</li></ul><hr><h2 id="_2-战斗系统最小骨架" tabindex="-1">2. 战斗系统最小骨架 <a class="header-anchor" href="#_2-战斗系统最小骨架" aria-label="Permalink to “2. 战斗系统最小骨架”">​</a></h2><p>可以先用一句话记：</p><blockquote><p><strong>战斗系统 = 战斗对象 + 战斗组件 + 状态数据 + 命中流程 + UI反馈 + 可扩展规则</strong></p></blockquote><p>最小闭环通常至少包含：</p><ul><li>攻击者</li><li>受击者</li><li>生命值</li><li>伤害来源</li><li>命中或触发条件</li><li>受伤后的状态变化</li><li>UI 或表现反馈</li></ul><p>如果缺少其中任一环，系统就容易“能播动作但不扣血”或“扣了血但玩家看不出来”。</p><hr><h2 id="_3-从现有证据能确认什么" tabindex="-1">3. 从现有证据能确认什么 <a class="header-anchor" href="#_3-从现有证据能确认什么" aria-label="Permalink to “3. 从现有证据能确认什么”">​</a></h2><h3 id="_3-1-战斗类组件存在清晰分类" tabindex="-1">3.1 战斗类组件存在清晰分类 <a class="header-anchor" href="#_3-1-战斗类组件存在清晰分类" aria-label="Permalink to “3.1 战斗类组件存在清晰分类”">​</a></h3><p>根据脚本界面截图，可直接确认战斗分类至少包含：</p><ul><li>生命</li><li>伤害</li><li>武器槽</li><li>远程武器</li><li>近战武器</li><li>子弹</li></ul><p>这意味着创游世界并不是把战斗全部塞进一个黑箱组件里，而是把战斗拆成多个职责模块。</p><h3 id="_3-2-这套拆分很像标准游戏架构" tabindex="-1">3.2 这套拆分很像标准游戏架构 <a class="header-anchor" href="#_3-2-这套拆分很像标准游戏架构" aria-label="Permalink to “3.2 这套拆分很像标准游戏架构”">​</a></h3><p>可以粗略理解为：</p><ul><li><code>生命</code>：负责承受伤害、记录血量</li><li><code>伤害</code>：负责定义或处理伤害行为</li><li><code>武器槽</code>：负责装备/切换/持有武器</li><li><code>近战武器</code>：负责近身攻击类逻辑</li><li><code>远程武器</code>：负责投射/射击类逻辑</li><li><code>子弹</code>：负责飞行物或命中载体</li></ul><p>这比“一个对象自己处理所有战斗逻辑”更容易扩展。</p><hr><h2 id="_4-推荐的战斗对象分层" tabindex="-1">4. 推荐的战斗对象分层 <a class="header-anchor" href="#_4-推荐的战斗对象分层" aria-label="Permalink to “4. 推荐的战斗对象分层”">​</a></h2><h3 id="_4-1-角色本体层" tabindex="-1">4.1 角色本体层 <a class="header-anchor" href="#_4-1-角色本体层" aria-label="Permalink to “4.1 角色本体层”">​</a></h3><p>角色本体更适合承载：</p><ul><li>生命值</li><li>阵营</li><li>当前状态（受击、闪避、死亡、霸体等）</li><li>移动/朝向</li><li>武器槽</li></ul><h3 id="_4-2-武器层" tabindex="-1">4.2 武器层 <a class="header-anchor" href="#_4-2-武器层" aria-label="Permalink to “4.2 武器层”">​</a></h3><p>武器更适合承载：</p><ul><li>攻击方式</li><li>攻击参数</li><li>冷却时间</li><li>命中范围</li><li>子弹生成规则</li></ul><h3 id="_4-3-子弹-命中特效层" tabindex="-1">4.3 子弹 / 命中特效层 <a class="header-anchor" href="#_4-3-子弹-命中特效层" aria-label="Permalink to “4.3 子弹 / 命中特效层”">​</a></h3><p>子弹或攻击体更适合承载：</p><ul><li>飞行表现</li><li>命中检测</li><li>命中后广播/触发</li><li>命中特效</li><li>自动销毁</li></ul><h3 id="_4-4-ui-层" tabindex="-1">4.4 UI 层 <a class="header-anchor" href="#_4-4-ui-层" aria-label="Permalink to “4.4 UI 层”">​</a></h3><p>UI 更适合承载：</p><ul><li>血条显示</li><li>伤害数字</li><li>技能冷却</li><li>武器/弹药显示</li><li>受伤提示</li></ul><p>别把核心扣血逻辑写死在 UI 里。UI 负责显示，地图/对象脚本负责真实状态。</p><hr><h2 id="_5-一个标准受伤流程该怎么想" tabindex="-1">5. 一个标准受伤流程该怎么想 <a class="header-anchor" href="#_5-一个标准受伤流程该怎么想" aria-label="Permalink to “5. 一个标准受伤流程该怎么想”">​</a></h2><p>推荐把“攻击命中”拆成这几步：</p><ol><li>攻击动作开始</li><li>生成攻击判定或子弹</li><li>命中目标</li><li>判断是否允许受伤 <ul><li>是否同阵营</li><li>是否无敌</li><li>是否已死亡</li><li>是否在特殊状态</li></ul></li><li>计算伤害</li><li>扣除生命</li><li>触发反馈 <ul><li>飘字</li><li>受击动画</li><li>击退</li><li>音效</li><li>血条变化</li></ul></li><li>判断是否死亡</li><li>若死亡，进入掉落/结算/广播</li></ol><p>这样设计的好处是：以后你要加暴击、护盾、Buff、破甲、元素伤害，都有位置可插。</p><hr><h2 id="_6-状态应该放在哪里" tabindex="-1">6. 状态应该放在哪里 <a class="header-anchor" href="#_6-状态应该放在哪里" aria-label="Permalink to “6. 状态应该放在哪里”">​</a></h2><h3 id="_6-1-放在自身层的状态" tabindex="-1">6.1 放在自身层的状态 <a class="header-anchor" href="#_6-1-放在自身层的状态" aria-label="Permalink to “6.1 放在自身层的状态”">​</a></h3><p>适合放角色自身属性：</p><ul><li>当前生命值</li><li>最大生命值</li><li>当前是否无敌</li><li>当前是否闪避中</li><li>当前装备武器</li><li>当前攻击冷却</li></ul><h3 id="_6-2-放在地图层的状态" tabindex="-1">6.2 放在地图层的状态 <a class="header-anchor" href="#_6-2-放在地图层的状态" aria-label="Permalink to “6.2 放在地图层的状态”">​</a></h3><p>适合放地图公共状态：</p><ul><li>当前波次</li><li>敌人总数</li><li>剩余敌人数</li><li>本局总击杀数</li><li>战斗是否开始</li><li>Boss 是否已登场</li></ul><h3 id="_6-3-放在系统层的状态" tabindex="-1">6.3 放在系统层的状态 <a class="header-anchor" href="#_6-3-放在系统层的状态" aria-label="Permalink to “6.3 放在系统层的状态”">​</a></h3><p>适合放全局流程：</p><ul><li>游戏胜负</li><li>总计时器</li><li>联机公共变量</li><li>跨地图战斗状态</li></ul><hr><h2 id="_7-血条系统为什么总是核心练手题" tabindex="-1">7. 血条系统为什么总是核心练手题 <a class="header-anchor" href="#_7-血条系统为什么总是核心练手题" aria-label="Permalink to “7. 血条系统为什么总是核心练手题”">​</a></h2><p>B站上“血条系统”类视频很多，不是巧合，而是因为它刚好把几个核心子系统串起来：</p><ul><li>生命值</li><li>伤害</li><li>UI</li><li>动画或渐变</li><li>数据同步</li></ul><p>也就是说，谁把血条做好了，通常已经开始摸到真正的系统设计。</p><p>一个完整血条至少要想清：</p><ul><li>它读谁的生命值</li><li>它什么时候刷新</li><li>它是直接绑属性，还是通过广播更新</li><li>它是否要做平滑变化</li><li>它是否区分“即时血条”和“延迟血条”</li></ul><hr><h2 id="_8-动作战斗为什么会引出状态机问题" tabindex="-1">8. 动作战斗为什么会引出状态机问题 <a class="header-anchor" href="#_8-动作战斗为什么会引出状态机问题" aria-label="Permalink to “8. 动作战斗为什么会引出状态机问题”">​</a></h2><p>像跑步、闪避、翻滚、滑铲这类功能，看起来只是动作，实际上会逼你面对状态机：</p><ul><li>正在跑步时能不能攻击？</li><li>闪避期间能不能受伤？</li><li>翻滚期间要不要隐藏血条或伤害提示？</li><li>受击时能不能打断当前动作？</li></ul><p>如果这些规则不清楚，战斗系统会变得很乱。</p><p>所以推荐至少有一个最简状态表：</p><ul><li>待机</li><li>移动</li><li>攻击</li><li>受击</li><li>闪避</li><li>死亡</li></ul><p>然后逐步定义：</p><ul><li>哪些状态能进入哪些状态</li><li>哪些状态会锁输入</li><li>哪些状态免伤</li><li>哪些状态结束后回到待机</li></ul><hr><h2 id="_9-推荐的第一版项目实现顺序" tabindex="-1">9. 推荐的第一版项目实现顺序 <a class="header-anchor" href="#_9-推荐的第一版项目实现顺序" aria-label="Permalink to “9. 推荐的第一版项目实现顺序”">​</a></h2><p>如果你现在就要做，建议按这个顺序：</p><h3 id="第一步-做角色生命系统" tabindex="-1">第一步：做角色生命系统 <a class="header-anchor" href="#第一步-做角色生命系统" aria-label="Permalink to “第一步：做角色生命系统”">​</a></h3><p>先有：</p><ul><li>最大生命</li><li>当前生命</li><li>扣血</li><li>死亡</li></ul><h3 id="第二步-做最小攻击闭环" tabindex="-1">第二步：做最小攻击闭环 <a class="header-anchor" href="#第二步-做最小攻击闭环" aria-label="Permalink to “第二步：做最小攻击闭环”">​</a></h3><p>先不求华丽，只做：</p><ul><li>攻击动作</li><li>命中目标</li><li>扣血</li></ul><h3 id="第三步-做血条显示" tabindex="-1">第三步：做血条显示 <a class="header-anchor" href="#第三步-做血条显示" aria-label="Permalink to “第三步：做血条显示”">​</a></h3><p>把角色状态可视化。</p><h3 id="第四步-做一种武器" tabindex="-1">第四步：做一种武器 <a class="header-anchor" href="#第四步-做一种武器" aria-label="Permalink to “第四步：做一种武器”">​</a></h3><p>选近战或远程先做一种，不要一起上。</p><h3 id="第五步-补表现" tabindex="-1">第五步：补表现 <a class="header-anchor" href="#第五步-补表现" aria-label="Permalink to “第五步：补表现”">​</a></h3><ul><li>飘字</li><li>受击反馈</li><li>震动/变色/闪烁</li><li>音效</li></ul><h3 id="第六步-补状态系统" tabindex="-1">第六步：补状态系统 <a class="header-anchor" href="#第六步-补状态系统" aria-label="Permalink to “第六步：补状态系统”">​</a></h3><ul><li>闪避</li><li>Buff</li><li>冷却</li><li>无敌帧</li></ul><h3 id="第七步-再做系统化扩展" tabindex="-1">第七步：再做系统化扩展 <a class="header-anchor" href="#第七步-再做系统化扩展" aria-label="Permalink to “第七步：再做系统化扩展”">​</a></h3><ul><li>多武器切换</li><li>子弹类型分化</li><li>概率触发另一种子弹</li><li>背包携带战斗道具</li><li>UI 与地图广播解耦</li></ul><hr><h2 id="_10-很常见的几个坑" tabindex="-1">10. 很常见的几个坑 <a class="header-anchor" href="#_10-很常见的几个坑" aria-label="Permalink to “10. 很常见的几个坑”">​</a></h2><h3 id="坑-1-把所有逻辑都写在一个对象里" tabindex="-1">坑 1：把所有逻辑都写在一个对象里 <a class="header-anchor" href="#坑-1-把所有逻辑都写在一个对象里" aria-label="Permalink to “坑 1：把所有逻辑都写在一个对象里”">​</a></h3><p>结果会变成后期一改就炸。应拆给：角色、武器、子弹、UI、地图。</p><h3 id="坑-2-ui-直接控制真实战斗结果" tabindex="-1">坑 2：UI 直接控制真实战斗结果 <a class="header-anchor" href="#坑-2-ui-直接控制真实战斗结果" aria-label="Permalink to “坑 2：UI 直接控制真实战斗结果”">​</a></h3><p>UI 更适合发请求，不适合做最终裁决。</p><h3 id="坑-3-攻击判定和伤害结算混成一块" tabindex="-1">坑 3：攻击判定和伤害结算混成一块 <a class="header-anchor" href="#坑-3-攻击判定和伤害结算混成一块" aria-label="Permalink to “坑 3：攻击判定和伤害结算混成一块”">​</a></h3><p>以后加护盾、暴击、减伤会很难插进去。</p><h3 id="坑-4-状态不分层" tabindex="-1">坑 4：状态不分层 <a class="header-anchor" href="#坑-4-状态不分层" aria-label="Permalink to “坑 4：状态不分层”">​</a></h3><p>把临时变量、角色状态、地图流程、全局流程混着放，后面联机会特别痛苦。</p><h3 id="坑-5-一开始就追求大而全" tabindex="-1">坑 5：一开始就追求大而全 <a class="header-anchor" href="#坑-5-一开始就追求大而全" aria-label="Permalink to “坑 5：一开始就追求大而全”">​</a></h3><p>推荐先把“能打 + 能掉血 + 能显示”做稳定，再往上加花活。</p><hr><h2 id="_13-结论等级与待验证问题" tabindex="-1">13. 结论等级与待验证问题 <a class="header-anchor" href="#_13-结论等级与待验证问题" aria-label="Permalink to “13. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 从现有脚本界面截图可以直接确认，战斗相关能力并不是一个黑箱，而是至少拆成生命、伤害、武器槽、近战武器、远程武器、子弹等多个类别。</li><li><code>[已确认]</code> UI 不应作为真实扣血与战斗结果的最终裁决层，它更适合作为反馈显示层。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 把战斗对象拆成角色本体、武器、子弹/攻击体、UI 四层，会比把逻辑堆在一个对象里更适合后续扩展。</li><li><code>[高可信推断]</code> 先搭“生命—命中—扣血—反馈”的最小闭环，再补武器、Buff、状态机，是大多数项目更稳的实现顺序。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 不同版本的具体组件参数、默认行为与可组合方式，可能与当前截图主证据存在差异。</li><li><code>[待验证]</code> 联机环境下战斗状态同步、伤害结算归属与 UI 延迟显示，仍需专题级进一步验证。</li></ul><h2 id="_14-常见误区补充" tabindex="-1">14. 常见误区补充 <a class="header-anchor" href="#_14-常见误区补充" aria-label="Permalink to “14. 常见误区补充”">​</a></h2><ul><li>许多人把“攻击动作播放出来了”误认为“战斗系统已经成立”，但如果没有命中、状态判断和反馈闭环，本质上还只是表现层。</li><li>一开始就做多武器、多段连招、复杂 Buff，通常会掩盖底层命中流程和状态边界还没稳定的问题。</li><li>只盯着单个战斗教程，很容易学会一个效果，却学不会可扩展的职责拆分。</li></ul><h2 id="_15-关联阅读" tabindex="-1">15. 关联阅读 <a class="header-anchor" href="#_15-关联阅读" aria-label="Permalink to “15. 关联阅读”">​</a></h2><p>建议配合阅读：</p><ul><li><code>docs/脚本系统/脚本界面与积木知识索引.md</code><ul><li>看战斗分类和脚本入口</li></ul></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code><ul><li>看状态应该放哪层</li></ul></li><li><code>docs/教程资料/专题研究/UI系统与切换机制解析.md</code><ul><li>看血条、冷却、反馈如何挂到 UI</li></ul></li><li><code>docs/脚本系统/专题研究/创游世界动作状态机入门.md</code><ul><li>看动作冲突、中断规则、输入锁如何组织</li></ul></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code><ul><li>看战斗系统放进整体项目时该怎么拆层</li></ul></li><li><code>docs/教程资料/B站创游世界视频资源清单.md</code><ul><li>找血条、翻滚、滑铲、Buff、换弹等案例视频</li></ul></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code><ul><li>追溯具体截图证据页</li></ul></li><li><code>docs/元信息/创游世界术语表.md</code><ul><li>统一理解生命、伤害、武器槽、状态等术语</li></ul></li></ul><hr><h2 id="_12-当前结论" tabindex="-1">12. 当前结论 <a class="header-anchor" href="#_12-当前结论" aria-label="Permalink to “12. 当前结论”">​</a></h2><p>基于现有资料，可以先得出一个很实用的结论：</p><blockquote><p><strong>创游世界的战斗系统并不是一块“战斗黑箱”，而是由生命、伤害、武器槽、近战、远程、子弹、UI 反馈和状态控制共同拼出来的。</strong></p></blockquote><p>所以真正有成长价值的，不是“背会某个战斗教程”，而是学会：</p><ul><li>怎么拆职责</li><li>怎么放状态</li><li>怎么让 UI 和对象逻辑分开</li><li>怎么给以后扩展留接口</li></ul>',122)])])}const b=i(d,[["render",h]]);export{u as __pageData,b as default};
